DROP TABLE IF EXISTS "admins";
DROP SEQUENCE IF EXISTS admins_id_seq;
CREATE SEQUENCE admins_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."admins" (
    "id" integer DEFAULT nextval('admins_id_seq') NOT NULL,
    "telegram_id" bigint NOT NULL,
    "role" admin_role NOT NULL,
    "display_name" character varying(255),
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "admins_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "admins_telegram_id_key" UNIQUE ("telegram_id")
) WITH (oids = false);

CREATE INDEX "ix_admins_telegram_id" ON "public"."admins" USING btree ("telegram_id");


DROP TABLE IF EXISTS "ai_knowledge_chunks";
DROP SEQUENCE IF EXISTS ai_knowledge_chunks_id_seq;
CREATE SEQUENCE ai_knowledge_chunks_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."ai_knowledge_chunks" (
    "id" integer DEFAULT nextval('ai_knowledge_chunks_id_seq') NOT NULL,
    "source_type" character varying(16) NOT NULL,
    "source_id" integer NOT NULL,
    "revision_id" integer,
    "language_code" character varying(8) NOT NULL,
    "chunk_index" integer NOT NULL,
    "title" character varying(500) NOT NULL,
    "content" text NOT NULL,
    "content_hash" character varying(64) NOT NULL,
    "embedding_model" character varying(128) NOT NULL,
    "embedding" vector(768) NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "ai_knowledge_chunks_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "uq_ai_knowledge_chunk_identity" UNIQUE ("source_type", "source_id", "revision_id", "language_code", "chunk_index")
) WITH (oids = false);

CREATE INDEX "ix_ai_knowledge_chunk_source" ON "public"."ai_knowledge_chunks" USING btree ("source_type", "source_id");

