DROP TABLE IF EXISTS "ai_knowledge_sync_jobs";
DROP SEQUENCE IF EXISTS ai_knowledge_sync_jobs_id_seq;
CREATE SEQUENCE ai_knowledge_sync_jobs_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."ai_knowledge_sync_jobs" (
    "id" integer DEFAULT nextval('ai_knowledge_sync_jobs_id_seq') NOT NULL,
    "page_id" integer,
    "revision_id" integer,
    "status" character varying(24) DEFAULT 'PENDING' NOT NULL,
    "attempts" integer DEFAULT '0' NOT NULL,
    "next_attempt_at" timestamptz DEFAULT now() NOT NULL,
    "last_error" character varying(255),
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    "faq_id" integer,
    "faq_revision_id" integer,
    CONSTRAINT "ai_knowledge_sync_jobs_page_id_key" UNIQUE ("page_id"),
    CONSTRAINT "ai_knowledge_sync_jobs_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "uq_ai_knowledge_sync_job_faq" UNIQUE ("faq_id"),
    CONSTRAINT "ck_ai_knowledge_sync_job_source" CHECK ((((page_id IS NOT NULL) AND (faq_id IS NULL) AND (revision_id IS NOT NULL) AND (faq_revision_id IS NULL)) OR ((page_id IS NULL) AND (faq_id IS NOT NULL) AND (revision_id IS NULL) AND (faq_revision_id IS NOT NULL))))
) WITH (oids = false);

CREATE INDEX "ix_ai_knowledge_sync_jobs_next_attempt_at" ON "public"."ai_knowledge_sync_jobs" USING btree ("next_attempt_at");

CREATE INDEX "ix_ai_knowledge_sync_jobs_status" ON "public"."ai_knowledge_sync_jobs" USING btree ("status");

