    "id" integer DEFAULT nextval('audit_logs_id_seq') NOT NULL,
    "admin_id" bigint NOT NULL,
    "action" character varying(64) NOT NULL,
    "entity_type" character varying(64) NOT NULL,
    "entity_id" character varying(64) NOT NULL,
