DROP TABLE IF EXISTS "bot_button_translations";
DROP SEQUENCE IF EXISTS bot_button_translations_id_seq;
CREATE SEQUENCE bot_button_translations_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."bot_button_translations" (
    "id" integer DEFAULT nextval('bot_button_translations_id_seq') NOT NULL,
    "button_id" integer NOT NULL,
    "language_code" language_code NOT NULL,
    "text" character varying(128) NOT NULL,
    CONSTRAINT "bot_button_translations_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "uq_button_language" UNIQUE ("button_id", "language_code")
) WITH (oids = false);

