DROP TABLE IF EXISTS "bot_buttons";
DROP SEQUENCE IF EXISTS bot_buttons_id_seq;
CREATE SEQUENCE bot_buttons_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."bot_buttons" (
    "id" integer DEFAULT nextval('bot_buttons_id_seq') NOT NULL,
    "page_id" integer NOT NULL,
    "text" text NOT NULL,
    "action_type" button_action NOT NULL,
    "target" character varying(512),
    "position" integer DEFAULT '0' NOT NULL,
    "row" integer DEFAULT '0' NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "bot_buttons_pkey" PRIMARY KEY ("id")
