    "created_by" bigint,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "bot_page_revisions_pkey" PRIMARY KEY ("id")
) WITH (oids = false);

CREATE INDEX "ix_bot_page_revisions_page_id" ON "public"."bot_page_revisions" USING btree ("page_id");

